import{n as e}from"./rolldown-runtime-B0Z9INg1.js";var t,n,r,i,a,o,s,c,l,u,d;function f(){return(f=e((()=>{t=`Angular`,n=`Native standalone Angular components, signals and Angular Forms from minerva-design/angular.`,r=`The native Angular package is available. Implemented components and platform differences are listed in the support matrix.`,i=`Platform support`,a={title:`Setup`,text:`Install minerva-design and the Angular peer versions declared by the package. Import the shared stylesheet once and bootstrap provideMinerva for theme and locale.`},o={title:`Signals and native imports`,text:`Import standalone directives and components directly. MnButton enhances a native button; MnInput and MnUpload expose typed value models. CUSTOM_ELEMENTS_SCHEMA is not needed.`},s={title:`Angular Forms`,text:`The native input and upload components include ControlValueAccessor support. Use ReactiveFormsModule or FormsModule directly; no custom value-accessor directive is required. Disabled, touched and value updates participate in the Angular form.`},c=`Upload selects and validates local files. The application handles network transfers: listen to filesSelected and update each UploadItem status as the transfer progresses.`,l=`Every component-page Angular tab runs native standalone Angular components with interactive inputs and outputs. Examples are compiled ahead of time with strict template checks; the displayed source matches the live preview. The separate Web Components guide remains available for custom-element integration.`,u=`Web Components in Angular`,d={title:t,description:n,scope:r,matrix:i,setup:a,signals:o,forms:s,upload:c,preview:l,wcGuide:u}})))()}f();export{d as default};